//! M9 词书与种子词库。
//!
//! 词书按学段 / 考试划分（小学、初中、高中、大学、雅思、专业），每个词书带一个
//! 难度系数（difficulty）：难度越高，SRS 首次复习间隔越短（更频繁巩固）。
//! 每个单词还可带内在难度（intrinsic difficulty，默认 1.0）做细粒度调整；
//! 学习新词时有效难度 = 词书难度 × 单词内在难度，快照写入 `word_states.difficulty`。
//! 迁移 1 已存在的 20 个种子单词会按难度映射进对应词书，保持数据唯一约束。

pub struct SeedWord {
    pub word: &'static str,
    pub phonetic: &'static str,
    pub meaning: &'static str,
    pub example_en: &'static str,
    pub example_zh: &'static str,
    pub difficulty: f64,
}

pub struct SeedBook {
    pub code: &'static str,
    pub title: &'static str,
    pub description: &'static str,
    pub level: &'static str,
    pub difficulty: f64,
    pub sort_order: i64,
    pub words: &'static [SeedWord],
}

/// 内在难度 1.0（常规单词）。
const fn w(
    word: &'static str,
    phonetic: &'static str,
    meaning: &'static str,
    example_en: &'static str,
    example_zh: &'static str,
) -> SeedWord {
    SeedWord {
        word,
        phonetic,
        meaning,
        example_en,
        example_zh,
        difficulty: 1.0,
    }
}

/// 内在难度 1.25（较难单词）。
const fn hw(
    word: &'static str,
    phonetic: &'static str,
    meaning: &'static str,
    example_en: &'static str,
    example_zh: &'static str,
) -> SeedWord {
    SeedWord {
        word,
        phonetic,
        meaning,
        example_en,
        example_zh,
        difficulty: 1.25,
    }
}

/// 内在难度 1.5（专业长词等最难单词）。
const fn vw(
    word: &'static str,
    phonetic: &'static str,
    meaning: &'static str,
    example_en: &'static str,
    example_zh: &'static str,
) -> SeedWord {
    SeedWord {
        word,
        phonetic,
        meaning,
        example_en,
        example_zh,
        difficulty: 1.5,
    }
}

/// 内在难度 0.6（基础常见词，最容易）。
const fn ew(
    word: &'static str,
    phonetic: &'static str,
    meaning: &'static str,
    example_en: &'static str,
    example_zh: &'static str,
) -> SeedWord {
    SeedWord {
        word,
        phonetic,
        meaning,
        example_en,
        example_zh,
        difficulty: 0.6,
    }
}

/// 内在难度 0.8（较容易词）。
const fn lw(
    word: &'static str,
    phonetic: &'static str,
    meaning: &'static str,
    example_en: &'static str,
    example_zh: &'static str,
) -> SeedWord {
    SeedWord {
        word,
        phonetic,
        meaning,
        example_en,
        example_zh,
        difficulty: 0.8,
    }
}

/// 内在难度 0.9（略容易词）。
const fn sw(
    word: &'static str,
    phonetic: &'static str,
    meaning: &'static str,
    example_en: &'static str,
    example_zh: &'static str,
) -> SeedWord {
    SeedWord {
        word,
        phonetic,
        meaning,
        example_en,
        example_zh,
        difficulty: 0.9,
    }
}

/// 内在难度 1.1（略难词）。
const fn nw(
    word: &'static str,
    phonetic: &'static str,
    meaning: &'static str,
    example_en: &'static str,
    example_zh: &'static str,
) -> SeedWord {
    SeedWord {
        word,
        phonetic,
        meaning,
        example_en,
        example_zh,
        difficulty: 1.1,
    }
}

/// 内在难度 1.2（较难词）。
const fn dw(
    word: &'static str,
    phonetic: &'static str,
    meaning: &'static str,
    example_en: &'static str,
    example_zh: &'static str,
) -> SeedWord {
    SeedWord {
        word,
        phonetic,
        meaning,
        example_en,
        example_zh,
        difficulty: 1.2,
    }
}

/// 内在难度 1.4（很难词）。
const fn tw(
    word: &'static str,
    phonetic: &'static str,
    meaning: &'static str,
    example_en: &'static str,
    example_zh: &'static str,
) -> SeedWord {
    SeedWord {
        word,
        phonetic,
        meaning,
        example_en,
        example_zh,
        difficulty: 1.4,
    }
}

